@tenacity.retry(stop=tenacity.stop_after_attempt(5), wait=tenacity.wait_exponential(multiplier=2, min=5, max=30), reraise=True)
def sync_s3(from_path, to_path, extra_options=None, extra_env=None, ardoq_region_set=True):
    logger.info('sync S3 {} to {}'.format(from_path, to_path))
    subprocess.check_call(
        ['aws', 's3', 'sync', '--quiet', '--no-progress', '--delete']
        + (['--region', os.getenv('AWS_REGION')] if ardoq_region_set else [])
        + [from_path, to_path],
        env={**os.environ, **(extra_env or {})})

def restore_org(config, source_org_label, target_org_label):
    try:
        logger.info("Restoring {} into {}".format(source_org_label, target_org_label))
        attachment_type = "s3" if config.attachments_bucket else "local"
        bucket_or_path = config.attachments_bucket if attachment_type=="s3" else "."

        restore_postgres_schema(config, source_org_label, target_org_label)

        target_org_data = org_data(config, target_org_label)[0]
        source_org_id = source_org_mapping.get(source_org_label)
        target_org_id = target_org_data['_id']

        source_dir_path = config.attachments_src_dir + '/' + source_org_id
        if attachment_type=="local":
            target_dir_path = config.attachments_dest_dir + '/' + target_org_id
            logger.info(f"Moving attachments directory {source_dir_path} to {target_dir_path}")

            shutil.rmtree(target_dir_path, ignore_errors=True)
            shutil.move(source_dir_path, target_dir_path)
        else:
            sync_s3(source_dir_path,
                    's3://{}/{}'.format(config.attachments_bucket, target_org_id),
                    extra_env={'LC_ALL': 'en_US.UTF-8',
                               'AWS_RETRY_MODE': 'standard',
                               'AWS_MAX_ATTEMPTS': '5'})
        update_attachments_and_permissions(config, source_org_id, source_org_label, target_org_id, attachment_type, bucket_or_path)

        logger.info(f"Done restoring {source_org_label} to {target_org_label}")
    except Exception as err:
        logger.exception(err)


